    laws: { press: ['censored', 'propaganda'], security: ['police', 'secret', 'terror'], land: ['collective', 'commune', 'smallholder'], labor: ['company', 'banned'], religion: ['secular', 'atheism'], trade: ['autarky', 'protect'] },
    lawDef: { press: 'censored', security: 'secret', land: 'commune', labor: 'company', religion: 'atheism', trade: 'autarky' },
    dip: { export: 0.7, agg: 0.5, trade: 0.3, cb: ['liberate'] },
    flags: { fiveYear: 1, partisans: 1, satellite: 1 },
    drift: [
      { to: 'personalist', label: 'The Great Helmsman', why: 'A charismatic chairman plus total propaganda dissolves the party into his person.',
        pressure: (n) => b(n.charisma > 70) * 0.4 + b(L(n, 'press', 'propaganda')) * 0.4 + b(n.bureau > 50) * 0.3 - 0.4 },
      { to: 'marketsoc', label: 'The capitalist roaders', why: 'A tired revolution and a strong apparatus choose growth over struggle.',
        pressure: (n) => b(n.dist > 55) * 0.5 + b(n.fervor < 25) * 0.4 + b(P(n, 'bureaucracy') > 30) * 0.3 - 0.4 },
    ],
    objective: { name: 'Surround the Cities', desc: 'Defeat a power with twice your industry, keep the peasantry with you, and bring a quarter of the world’s people into your camp.',
      parts: (n, G) => [['Beat a state with twice your industry', b(n.flags.beatStronger), 1], ['Peasant support at 65 or above', b(S(n, 'peasants') >= 65), 1], ['World population in your camp', ID.campShare(G, n), 0.25, '%']] },
    perks: ['People’s war: infiltration attacks at +50%, strong in forest, hills and mountains.', 'Occupied home provinces bleed the occupier every month.', 'Agriculture yields 15% more; the peasantry is your base, not your problem.', 'Mass campaigns can reset bureaucratisation — at a price.'],
