    doctrine: { atk: 0.95, def: 1.05, home: 1.15, morale: 'workers', styles: { advance: 1, assault: 0.8, blitz: 0.9, infiltrate: 0.9, siege: 1.0 } },
    fbase: { workers: 14, peasants: 4, capital: -22, military: -8, clergy: -8, intelligentsia: 10, bureaucracy: 4 },
    fpow: { capital: 0.9, workers: 1.4 }, ruling: ['workers', 'intelligentsia'],
