    laws: { press: ['propaganda', 'censored'], security: ['secret', 'terror', 'police'], land: ['collective'], labor: ['company', 'banned'], religion: ['atheism', 'secular'], trade: ['autarky', 'protect'] },
    lawDef: { press: 'propaganda', security: 'secret', land: 'collective', labor: 'company', religion: 'atheism', trade: 'autarky' },
