    laws: { press: ['propaganda'], security: ['terror'], land: ['landlord', 'smallholder', 'collective'], labor: ['banned'], religion: ['statechurch', 'tolerance', 'secular', 'atheism'], trade: ['autarky'] },
    lawDef: { press: 'propaganda', security: 'terror', land: 'landlord', labor: 'banned', religion: 'tolerance', trade: 'autarky' },
