    legit: { prosperity: 0.65, order: 0.2, competence: 0.15 },
    laws: { press: ['free'], security: ['liberties', 'police'], land: ['landlord', 'smallholder'], labor: ['free', 'company'], religion: ['tolerance'], trade: ['free'] },
